//! Command-line interface. `--help` is generated by clap from the definitions below, and
//! the section flags are generated from [`SectionKind::spec`].

use clap::{Arg, ArgAction, ArgMatches, Args, ColorChoice, Command, FromArgMatches, Parser};

use crate::analysis::{Grouping, Limit, Settings};
use crate::render::View;
use crate::render::table::Show;
use crate::sections::SectionKind;

/// Explains where your RAM is going
#[derive(Parser)]
#[command(
    version,
    disable_help_flag = true,
    after_help = "With no section flags, prints the overview and the programs.\n\
                  Run with sudo to include other users' processes and kernel slab caches."
)]
pub struct Cli {
    #[command(flatten)]
    sections: SectionFlags,

    /// Print every section, and break the overview down by category
    #[arg(short, long)]
    detailed: bool,

    /// List all programs
    #[arg(short, long, conflicts_with = "top")]
    all: bool,

    /// How many programs to list
    #[arg(long, value_name = "N", default_value_t = 15)]
    top: usize,

    /// How many slab caches to list
    #[arg(long, value_name = "N", default_value_t = 12)]
    slabs: usize,

    /// List processes one by one instead of grouping them by program
    #[arg(short = 'P', long)]
    per_process: bool,

    #[command(flatten)]
    show: ShowFlags,

    /// When to use colors
    #[arg(long, value_enum, default_value_t)]
    color: ColorChoice,

    /// Print help
    #[arg(long, action = ArgAction::HelpShort)]
    help: (),
}

impl Cli {
    pub fn settings(&self) -> Settings {
        Settings {
            programs: if self.all { Limit::All } else { Limit::Top(self.top) },
            grouping: if self.per_process { Grouping::PerProcess } else { Grouping::ByProgram },
            slabs: Limit::Top(self.slabs),
        }
    }

    pub fn view(&self) -> View {
        let sections = match (self.sections.0.as_slice(), self.detailed) {
            ([], true) => SectionKind::ALL.to_vec(),
            ([], false) => SectionKind::SUMMARY.to_vec(),
            (chosen, _) => chosen.to_vec(),
        };
        View { sections, breakdown: self.detailed, show: self.show.0 }
    }

    pub fn color(&self) -> anstream::ColorChoice {
        match self.color {
            ColorChoice::Auto => anstream::ColorChoice::Auto,
            ColorChoice::Always => anstream::ColorChoice::Always,
            ColorChoice::Never => anstream::ColorChoice::Never,
        }
    }
}

/// One flag per section, generated from [`SectionKind::spec`]; holds the chosen sections
/// in report order.
struct SectionFlags(Vec<SectionKind>);

impl FromArgMatches for SectionFlags {
    fn from_arg_matches(matches: &ArgMatches) -> Result<Self, clap::Error> {
        let chosen = SectionKind::ALL.into_iter().filter(|kind| matches.get_flag(kind.spec().flag));
        Ok(Self(chosen.collect()))
    }

    fn update_from_arg_matches(&mut self, matches: &ArgMatches) -> Result<(), clap::Error> {
        *self = Self::from_arg_matches(matches)?;
        Ok(())
    }
}

impl Args for SectionFlags {
    fn augment_args(command: Command) -> Command {
        command.args(SectionKind::ALL.map(|kind| {
            let spec = kind.spec();
            Arg::new(spec.flag)
                .short(spec.short)
                .long(spec.flag)
                .help(spec.about)
                .action(ArgAction::SetTrue)
        }))
    }

    fn augment_args_for_update(command: Command) -> Command {
        Self::augment_args(command)
    }
}

/// `-h`/`-H` switch headers on and off (the last one wins); `-n` hides help text.
struct ShowFlags(Show);

const HEADERS: &str = "headers";
const NO_HEADERS: &str = "no-headers";
const NO_HELP: &str = "no-help";

impl FromArgMatches for ShowFlags {
    fn from_arg_matches(matches: &ArgMatches) -> Result<Self, clap::Error> {
        Ok(Self(Show { headers: !matches.get_flag(NO_HEADERS), help: !matches.get_flag(NO_HELP) }))
    }

    fn update_from_arg_matches(&mut self, matches: &ArgMatches) -> Result<(), clap::Error> {
        *self = Self::from_arg_matches(matches)?;
        Ok(())
    }
}

impl Args for ShowFlags {
    fn augment_args(command: Command) -> Command {
        command.args([
            Arg::new(HEADERS)
                .short('h')
                .long(HEADERS)
                .help("Print titles, column headers and totals (the default)")
                .action(ArgAction::SetTrue)
                .overrides_with(NO_HEADERS),
            Arg::new(NO_HEADERS)
                .short('H')
                .long(NO_HEADERS)
                .help("Leave out titles, column headers and totals")
                .action(ArgAction::SetTrue)
                .overrides_with(HEADERS),
            Arg::new(NO_HELP)
                .short('n')
                .long(NO_HELP)
                .help("Leave out explanations and warnings")
                .action(ArgAction::SetTrue),
        ])
    }

    fn augment_args_for_update(command: Command) -> Command {
        Self::augment_args(command)
    }
}

#[cfg(test)]
mod tests {
    use clap::CommandFactory;

    use super::*;

    fn parse(args: &[&str]) -> Cli {
        Cli::try_parse_from(std::iter::once("memori").chain(args.iter().copied())).unwrap()
    }

    #[test]
    fn definition_is_consistent() {
        Cli::command().debug_assert();
    }

    #[test]
    fn readme_shows_the_real_help() {
        let help = Cli::command().render_help().to_string();
        let readme = include_str!("../README.md");
        assert!(
            readme.contains(&help),
            "README.md is out of date; replace its usage block with:\n\n{help}"
        );
    }

    #[test]
    fn help_lists_itself() {
        assert!(Cli::command().render_help().to_string().contains("--help"));
    }

    #[test]
    fn chooses_sections() {
        assert_eq!(parse(&[]).view().sections, SectionKind::SUMMARY);
        assert_eq!(parse(&["-d"]).view().sections, SectionKind::ALL);
        assert_eq!(parse(&["-zp"]).view().sections, [SectionKind::Programs, SectionKind::Zfs]);
    }

    #[test]
    fn last_header_flag_wins() {
        assert!(!parse(&["-hH"]).view().show.headers);
        assert!(parse(&["-Hh"]).view().show.headers);
        assert!(!parse(&["-n"]).view().show.help);
    }

    #[test]
    fn all_and_top_are_exclusive() {
        assert_eq!(parse(&["-a"]).settings().programs, Limit::All);
        assert_eq!(parse(&["--top", "3"]).settings().programs, Limit::Top(3));
        assert!(Cli::try_parse_from(["memori", "-a", "--top", "3"]).is_err());
    }
}
